CREATE TABLE "run_clocks" (
  "run" text,
  "parent" text,
  "work_key" text NOT NULL,
  "agent" text,
  "what" text NOT NULL,
  "started_at" bigint NOT NULL,
  "bound_ms" bigint NOT NULL,
  "ended_at" bigint,
  PRIMARY KEY ("run")
);

CREATE INDEX "run_clocks_parent" ON "run_clocks" ("parent");

CREATE TABLE "clock_asks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "run" text NOT NULL,
  "facts" text NOT NULL,
  "asked_at" bigint NOT NULL,
  "answer_by" bigint NOT NULL,
  "verdict" text,
  "kept_until" bigint,
  "decided_by" text,
  "why" text,
  "closed_at" bigint,
  PRIMARY KEY ("id")
);

CREATE INDEX "clock_asks_run" ON "clock_asks" ("run");
